import {ReactNode,useEffect,useState} from 'react';
export function PixelLoader({label,active=true}:{label:string;active?:boolean}){const [elapsed,setElapsed]=useState(0);useEffect(()=>{if(!active)return;const start=Date.now(),id=setInterval(()=>setElapsed((Date.now()-start)/1000),100);return()=>clearInterval(id)},[active]);return <span className="bui-loader"><span className={`bui-grid ${active?'is-active':''}`} aria-hidden="true">{Array.from({length:9},(_,i)=><i key={i}/>)}</span><span>{label}</span>{active&&<em>{elapsed.toFixed(1)}s</em>}</span>}
export function StreamText({children,run}:{children:string;run:boolean}){const words=children.split(' ');return <span className="bui-stream" aria-label={children}>{words.map((word,i)=><span key={i} style={{animationDelay:run?`${Math.min(i*22,700)}ms`:'0ms'}}>{word}{' '}</span>)}</span>}
export function SegmentedTrace({items}:{items:{label:string;content:ReactNode}[]}){const [active,setActive]=useState(0);return <div className="bui-trace"><div className="bui-trace-head"><PixelLoader label="Evidence trace" active={false}/><div role="tablist" aria-label="Evidence trace views">{items.map((x,i)=><button role="tab" aria-selected={i===active} onClick={()=>setActive(i)} key={x.label}>{x.label}</button>)}</div></div><div className="bui-trace-body" role="tabpanel" key={active}>{items[active].content}</div></div>}
